  size_t length = 0;

  const char *jpeg_version = "JPEG-6b";
  const char *description = "JPEG (Joint Photographic Experts Group)";

  MagickInfo *entry = (MagickInfo *) AcquireMagickMemory(sizeof(*entry));
  if (entry == (MagickInfo *) NULL)
    return length;

  entry->decoder = (MagickDecoder) JPEGImageDecoder;
  entry->encoder = (MagickEncoder) JPEGImageEncoder;
  entry->thread_support = MagickTrue;
  entry->mime_type = (char *) "image/jpeg";
  entry->description = (char *) ConstantString(description);
  entry->magick = (char *) "JPEG";
  entry->extension = (char *) "jpg";
  entry->signature = (unsigned char *) NULL;
  entry->signature_length = 0;

  magick_info = entry;
  magick_info->next = (MagickInfo *) NULL;

  RegisterMagickInfo(magick_info);

  magick_info = (MagickInfo *) CloneMagickMemory(entry);
  magick_info->magick = (char *) "JPG";
  magick_info->next = (MagickInfo *) NULL;

  RegisterMagickInfo(magick_info);

  magick_info = (MagickInfo *) CloneMagickMemory(entry);
  magick_info->magick = (char *) "JPE";
  magick_info->next = (MagickInfo *) NULL;

  RegisterMagickInfo(magick_info);

  magick_info = (MagickInfo *) CloneMagickMemory(entry);
  magick_info->magick = (char *) "PJPEG";
  magick_info->next = (MagickInfo *) NULL;

  RegisterMagickInfo(magick_info);

  magick_info = (MagickInfo *) CloneMagickMemory(entry);
  magick_info->magick = (char *) "JPS";
  magick_info->next = (MagickInfo *) NULL;

  RegisterMagickInfo(magick_info);

  length = sizeof(*entry);

  RelinquishMagickMemory(entry);

  return length;
}

size_t RegisterJPEGImage(void) {
  MagickInfo *magick_info;
  size_t length;

  const char *version = MagickLibVersionText;
  const char *description = "JPEG image format (ISO 10917-1)";
  char *mime_type = "image/jpeg";

  if (version != (const char *) NULL) {
    (void) CopyMagickString(magick_info->version, version, MAGICK_PATH_MAX);
    if (version != (const char *) NULL)
      magick_info->thread_support = MagickTrue;
  }

  magick_info = AcquireMagickInfo("JPEG", description);
  magick_info->decoder = JPEGReadImage;
  magick_info->encoder = JPEGWriteImage;
  magick_info->thread_support = MagickTrue;
  magick_info->mime_type = mime_type;
  magick_info->adjoin = MagickTrue;

  (void) RegisterMagickInfo(magick_info);

  length = MagickPathExtent;

  return (length);
}

