size_t RegisterJPEGImage(void) {
  MagickInfo *entry;

  entry = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
  (void) memset(entry, 0, sizeof(MagickInfo));
  entry->signature = MagickSignature;
  entry->decoder = JPEGDecodeImage;
  entry->encoder = JPEGEvaluateImage;
  entry->thread_support = MagickTrue;
  entry->mime_type = ConstantString("image/jpeg");
  entry->description = ConstantString("JPEG image format");

#if defined(JPEG_LIB_VERSION) && (JPEG_LIB_VERSION >= 62)
  if (jpeg_errno() == 0) {
    entry->thread_support = MagickTrue;
  }
  else {
    entry->thread_support = MagickFalse;
  }
#endif

  entry = CloneMagickInfo(entry);
  (void) RegisterMagickInfo("JPE", entry);
  (void) RegisterMagickInfo("JPEG", entry);
  (void) RegisterMagickInfo("JPG", entry);
  (void) RegisterMagickInfo("JPS", entry);
  (void) RegisterMagickInfo("PJPEG", entry);

  return sizeof(MagickInfo);
}

